#!/usr/bin/env python3
from pathlib import Path
import base64, gzip
p = Path("scripts/.mi_api_payload.txt")
p.write_text(p.read_text(encoding="ascii") + '', encoding="ascii")
target = Path("assets/api-mode.js")
target.write_bytes(gzip.decompress(base64.b64decode(p.read_text(encoding="ascii"))))
p.unlink(missing_ok=True)
print("Applied MI UI api-mode.js")
